import sys
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        a = []
        for _ in range(n):
            a.append(int(next(iterator)))
    except StopIteration:
        return

    if n == 1:
        print(a[0])
        return

    # The problem asks for the minimum possible final health.
    # Through analysis, the optimal strategy to minimize the final health
    # is equivalent to finding the Greatest Common Divisor (GCD) of all initial health values.
    # This is because we can effectively simulate the Euclidean algorithm steps
    # by having the smallest alive monster attack the largest, reducing the largest
    # modulo the smallest (conceptually), until one remains.

    result = a[0]
    for i in range(1, n):
        result = gcd(result, a[i])

    print(result)

if __name__ == '__main__':
    solve()
